diff.code:
// keep only the members of T assignable to U
type KeepAssignable<T, U> = T extends U ? T : never;

// true if T is exactly string
type IsString<T> = [T] extends [string] ? true : false;

// true if T is never
type IsNever<T> = T extends never ? true : false;

type A = KeepAssignable<string | number | boolean, string | number>;
type B = IsString<'a' | 'b'>;
type C = IsNever<never>;
